mapper.select:
select *
  from agent_key_file.report_task
 where batch_id = #{batchId}
   and task_type = #{taskType}
 order by attempt_no desc, create_time desc
 limit 1

mapper.update:
update agent_key_file.report_task
   set lease_until = #{leaseUntil}, update_time = #{now}
 where id = #{taskId} and status = 'PROCESSING'
   and lease_owner = #{leaseOwner} and lease_until >= #{now}

update agent_key_file.report_task
   set progress_percent = #{progressPercent}, result_summary = #{resultSummary},
       lease_until = #{leaseUntil}, update_time = #{now}
 where id = #{taskId} and status = 'PROCESSING'
   and lease_owner = #{leaseOwner} and lease_until >= #{now}
